// === Tab: mySketch ===
let vs = `
   precision highp float;

   attribute vec3 aPosition;
   attribute vec2 aTexCoord;
   varying vec2 vTexCoord;

   uniform mat4 uProjectionMatrix;
   uniform mat4 uModelViewMatrix;

   void main() {
      vec4 positionVec4 = vec4(aPosition, 1.0);
      vTexCoord = aTexCoord;
      gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
   }
`;

let fs = `
   precision highp float;

   varying vec2 vTexCoord;

   uniform float u_offset;
   uniform vec3 u_color;

   void main() {
      vec2 b = vTexCoord * 2.0 - 1.0;
      b.y += sin(b.x * 4.0 + u_offset) * sin(0.5 * 4.0) * 0.25;

      float cb = 1.0 - abs(sin(b.y));
      cb = pow(cb, 16.0);
      vec3 col = vec3(cb);
      col *= u_color ;

      float tr = (cb <= 0.6) ? 0.45*cb : 0.8 ;
      gl_FragColor = vec4(col, tr);
    }
`;

let theShader;

function setup() {
	 setAttributes("alpha", false);
   setAttributes("antialias", true);
   setAttributes("powerPreference", "high-performance");

   createCanvas(v=1112, w=834, WEBGL);


   theShader = createShader(vs, fs);

   colorMode(HSB);
   rectMode(CENTER);
   noStroke();
   background("#D0F0E0");

}

const wh = 200 ;

function draw(){
   let t = frameCount / 5;

   let r = radians(PI * (t + random(-1,1))) ;
   let x = width/2.5 * cos(r)  + random(-1,1)*10;
   let y = height/2.5 * sin(r) + random(-1,1)*10;

   let offset = 2*PI/10 * (t);
   let col = color((t*9)%360, 100, 100);
   col = [red(col)/255.0, green(col)/255.0, blue(col)/255.0]

   fill(100, 0);

   shader(theShader);
   theShader.setUniform('u_offset', offset);
   theShader.setUniform('u_color', col);
   push();
   translate(x, y);
   rotate(r+PI/2);
   rect(0, 0, wh, wh);
   pop();
   resetShader();
}

//save JPG
function mousePressed() {
   save("img_"+month()+day()+hour()+minute()+second()+".jpg");
}

